module.exports = /*#__PURE__*/JSON.parse('{"hero":{"badge":"Available for Research Opportunities","headlinePrefix":"Protecting","headlineSuffix":" the Next Generation of Networks","subheadlineLine1":"BSc Electronics & Telecommunication Engineering","subheadlineLine2":"Prospective MSc Cybersecurity Candidate","description":"Bridging the gap between telecommunications infrastructure and advanced network security. Passionate about protocol analysis, digital forensics, and building resilient systems.","primaryCta":{"text":"Explore Research","link":"#projects"},"secondaryCta":{"text":"View Curriculum Vitae","link":"/resume.pdf"}},"about":{"title":"Academic Background & Research Interests","paragraphs":["With a solid foundation in **Electronics & Telecommunication Engineering**, I possess a deep understanding of how data flows across physical and logical layers. During my undergraduate studies, I developed a keen interest in the security aspects of these communication networks.","My goal is to pursue an **MSc in Cybersecurity** to transition from understanding network architectures to actively securing them. I am particularly interested in academic research focusing on *network forensics, cryptographic protocols, and intrusion detection systems (IDS)*."]},"skills":{"title":"Technical Proficiency","categories":[{"id":"tools","title":"Security & Analysis Tools","items":"Wireshark, Nmap, Burp Suite, Metasploit, Snort","color":"primary"},{"id":"programming","title":"Programming & Scripting","items":"C/C++, Python, JavaScript/TypeScript, Bash","color":"accent"},{"id":"systems","title":"Systems & Infrastructure","items":"Linux Administration, TCP/IP Networking, Active Directory","color":"primary"},{"id":"learning","title":"Current Learning Focus","items":"Advanced Network Forensics, TryHackMe Pathways","color":"accent"}]},"projects":{"title":"Relevant Technical Projects","description":"Practical applications demonstrating my understanding of low-level networking and system security engineering.","list":[{"title":"Network Traffic Analyzer","description":"Developed a packet capture and analysis tool from scratch in C using libpcap. Features deep inspection of TCP/IP headers, payload extraction, and protocol statistics generation.","tech":["C","libpcap","TCP/IP"],"github":"#"},{"title":"Custom Port Scanner & Enumerator","description":"Engineered a lightweight, multithreaded port scanner in C. Implemented SYN scanning techniques and basic banner grabbing to understand the mechanics of network reconnaissance.","tech":["C","Sockets","Multithreading"],"github":"#"},{"title":"Linux Telemetry Daemon","description":"Built a CLI system monitoring tool that parses virtual file systems (/proc) to collect real-time CPU, memory, and process telemetry, vital for diagnosing system anomalies.","tech":["C","Linux API","Bash"],"github":"#"},{"title":"Vulnerability Research Lab","description":"A curated repository of practice scripts, mitigation strategies, and lab notes focused on OWASP Top 10 vulnerabilities, tested in isolated environments.","tech":["Python","Burp Suite","Web Sec"],"github":"#"}]},"blog":{"title":"Research & Publications","description":"Documenting my journey into cybersecurity. I write comprehensive articles focusing on protocol deep-dives, lab walk-throughs, and analytical research ahead of my graduate studies.","linkText":"Read my latest articles","linkUrl":"/blog"},"contact":{"title":"Get in Touch","description":"I am actively seeking opportunities to connect with professors, researchers, and professionals in the cybersecurity domain.","email":"fardin@example.com","socials":[{"name":"LinkedIn","link":"#"},{"name":"GitHub","link":"#"}]},"footer":{"name":"Md Fardin Ahamed","tagline":"Electronics & Telecommunication Engineering","subTagline":"Designed for MSc applications and cybersecurity recruiters."}}');

